-- Review before running. Additive schema only; does not delete existing data.
-- All tables have RLS enabled and no client-facing policies: privileged server routes only.
create table if not exists public.llm_providers (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, created_at timestamptz not null default now());
create table if not exists public.llm_models (id uuid primary key default gen_random_uuid(), provider_id uuid not null references public.llm_providers(id) on delete restrict, name text not null, model_id text not null, description text, is_active boolean not null default true, created_at timestamptz not null default now(), unique(provider_id,model_id));
create table if not exists public.terms (id uuid primary key default gen_random_uuid(), term text not null unique, definition text, created_at timestamptz not null default now());
create table if not exists public.ai_generation_examples (id uuid primary key default gen_random_uuid(), title text not null, input_text text not null, output_text text not null, created_at timestamptz not null default now());
create table if not exists public.prompt_chains (id uuid primary key default gen_random_uuid(), name text not null unique, description text, created_at timestamptz not null default now());
create table if not exists public.prompt_chain_steps (id uuid primary key default gen_random_uuid(), chain_id uuid not null references public.prompt_chains(id) on delete restrict, step_order integer not null check(step_order>=0), prompt_template text not null, created_at timestamptz not null default now(), unique(chain_id,step_order));
create table if not exists public.prompt_chain_mix (id uuid primary key default gen_random_uuid(), chain_id uuid not null unique references public.prompt_chains(id) on delete restrict, weight numeric not null default 1 check(weight>=0), is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.generation_requests (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, request_type text not null, status text not null default 'pending', created_at timestamptz not null default now());
create table if not exists public.llm_responses (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.generation_requests(id) on delete restrict, model_id uuid references public.llm_models(id) on delete set null, content text not null, created_at timestamptz not null default now());
create table if not exists public.allowed_signup_domains (id uuid primary key default gen_random_uuid(), domain text not null unique, description text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.whitelisted_emails (id uuid primary key default gen_random_uuid(), email text not null unique, description text, is_active boolean not null default true, created_at timestamptz not null default now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['llm_providers','llm_models','terms','ai_generation_examples','prompt_chains','prompt_chain_steps','prompt_chain_mix','generation_requests','llm_responses','allowed_signup_domains','whitelisted_emails'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
-- These records are intentionally NOT wired into the main app's generation or OAuth flow yet.
-- No example rows are fabricated. Existing application behavior remains unchanged.
